    __rwRoutes: any;
}>(): AppLink<App>;
export declare function defineLinks<const T extends readonly string[]>(routes: T): LinkFunction<T[number]>;
export {};

export function linkFor() {
    return createLinkFunction();
}
export function createLinks(_app) {
    return linkFor();
}
